import { Agent } from "../game";
import { COLORS, UNIT_VISUAL_HEIGHT, HUD_PADDING } from "../../constants";
import { HexUtils, MapConfig } from "../utils";
import { AssetManager } from "../assets";
import { Team } from "../../types";

// --- Constants ---
const GRAVITY = 200;
const TEXT_LIFESPAN = 1.0;
const BAR_WIDTH = 44;
const BAR_HEIGHT = 6;
const BAR_PADDING = 3;

interface FloatingText {
    active: boolean;
    x: number; 
    y: number;
    vx: number; 
    vy: number;
    text: string; 
    color: string;
    life: number; 
    maxLife: number;
    size: number;
    type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK';
    isUlt: boolean; 
}

export class HUDSystem {
    // Active Texts
    damageNumbers: FloatingText[] = [];

    // Memory Pool
    private pool: FloatingText[] = [];

    constructor() {
        for(let i=0; i<50; i++) this.pool.push(this.createEmpty());
    }

    public reset() {
        for (const d of this.damageNumbers) {
            this.release(d);
        }
        this.damageNumbers.length = 0;
    }

    private createEmpty(): FloatingText {
        return {
            active: false,
            x: 0, y: 0, vx: 0, vy: 0,
            text: '', color: '#fff', life: 0, maxLife: 0, size: 0,
            type: 'DAMAGE', isUlt: false
        };
    }

    public addFloatingText(x: number, y: number, text: string, color: string, size: number, type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK' = 'DAMAGE', isUlt: boolean = false) {
        if (type === 'KILL_STREAK') {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                if (this.damageNumbers[i].type === 'KILL_STREAK') {
                    this.release(this.damageNumbers[i]);
                    // Swap and pop for O(1) removal
                    this.damageNumbers[i] = this.damageNumbers[this.damageNumbers.length - 1];
                    this.damageNumbers.pop();
                }
            }
        }

        let vx = 0;
        let vy = 0;
        let life = TEXT_LIFESPAN;

        if (type === 'SHOUT') {
            if (isUlt) {
                vy = -5; 
                life = 2.5; 
                size = 24; 
            } else {
                vy = -20; 
                life = 1.2;
                size = 14; 
            }
        } else if (type === 'CC') {
            vy = -20; 
            life = 1.5;
        } else if (type === 'KILL_STREAK') {
            vx = 0;
            vy = -30;
            life = 3.5; 
            size = 32; 
        } else {
            vx = (Math.random() - 0.5) * 60; 
            vy = -100; 
        }

        let ft: FloatingText;
        if (this.pool.length > 0) {
            ft = this.pool.pop()!;
        } else {
            ft = this.createEmpty();
        }

        ft.active = true;
        ft.x = x; ft.y = y;
        ft.vx = vx; ft.vy = vy;
        ft.text = text; ft.color = color;
        ft.life = life; ft.maxLife = life;
        ft.size = size; ft.type = type;
        ft.isUlt = isUlt;

        this.damageNumbers.push(ft);
    }

    private release(ft: FloatingText) {
        ft.active = false;
        this.pool.push(ft);
    }

    update(dt: number) {
        const count = this.damageNumbers.length;
        // Iterate backwards for safe removal
        for (let i = count - 1; i >= 0; i--) { 
            const d = this.damageNumbers[i]; 
            d.life -= dt; 

            d.x += d.vx * dt;
            d.y += d.vy * dt; 

            if (d.type === 'DAMAGE' || d.type === 'HEAL') {
                d.vy += GRAVITY * dt;
            } else if (d.type === 'SHOUT' || d.type === 'CC') {
                d.vy *= 0.95; 
            } else if (d.type === 'KILL_STREAK') {
                d.vy *= 0.92; 
            }

            if (d.life <= 0) {
                this.release(d);
                // PERFORMANCE FIX: Swap-and-pop instead of splice(i,1)
                this.damageNumbers[i] = this.damageNumbers[this.damageNumbers.length - 1];
                this.damageNumbers.pop();
            }
        }
    }

    draw(ctx: CanvasRenderingContext2D, agents: Agent[], getTerrainHeight: (q: number, r: number) => number, mapConfig: MapConfig, highlight: Agent | null, time: number) {
        agents.forEach(a => {
            if (a.hp <= 0) return;
            if (a.spawnTimer > 0) return; 

            let h = 0;
            if (a.isMoving && a.path.length > 0) {
                const startH = getTerrainHeight(a.q, a.r);
                const endHex = a.path[0];
                const endH = getTerrainHeight(endHex.q, endHex.r);
                h = HexUtils.lerp(startH, endH, a.moveProgress);
            } else {
                const visualHex = HexUtils.fromPx(a.px, a.py, mapConfig);
                h = getTerrainHeight(visualHex.q, visualHex.r);
            }

            const groundY = a.py - h;
            const physicsOffsetY = a.physics.y - a.physics.z; 
            const anchorY = groundY - UNIT_VISUAL_HEIGHT + physicsOffsetY - HUD_PADDING;
            const headX = a.px + a.physics.x;

            const isSelected = (a === highlight);
            this.drawUnitBars(ctx, a, headX, anchorY, isSelected, time);
            this.drawUnitStatusGauges(ctx, a, headX, anchorY);
        });

        this.drawFloatingText(ctx);
    }

    private drawUnitStatusGauges(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number) {
        let activeTimer = 0;
        let maxTimer = 0;
        let iconType = '';
        let gaugeColor = '';

        if (agent.banished) {
            activeTimer = agent.banishTimer;
            maxTimer = agent.banishMax || activeTimer;

            if (agent.visualStatus === 'POLYMORPH') {
                iconType = 'POLYMORPH'; gaugeColor = '#d8b4fe';
            } else if (agent.visualStatus === 'STASIS') {
                iconType = 'STASIS'; gaugeColor = '#facc15';
            } else {
                iconType = 'BANISH'; gaugeColor = '#7e22ce';
            }
        } else if (agent.stunTimer > 0) {
            activeTimer = agent.stunTimer;
            maxTimer = agent.stunMax || activeTimer;
            iconType = 'STUN'; gaugeColor = '#fbbf24';
        } else if (agent.silenceTimer > 0) {
            activeTimer = agent.silenceTimer;
            maxTimer = agent.silenceMax || activeTimer;
            iconType = 'SILENCE'; gaugeColor = '#94a3b8';
        } else if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const progress = 1 - (agent.castTimer / skill.cast);
                this.drawCircularGauge(ctx, x, y, progress, skill.visual || 'BOLT', skill.color, true);
                return;
            }
        }

        if (iconType && maxTimer > 0) {
            const progress = activeTimer / maxTimer;
            this.drawCircularGauge(ctx, x, y, progress, iconType, gaugeColor, false);
        }
    }

    // 1. FACTION-BASED HP BARS REFACTOR
    private drawUnitBars(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, isSelected: boolean, time: number) {
        const hasMp = agent.maxMp > 0;

        const contentW = BAR_WIDTH;
        const hpHeight = BAR_HEIGHT;
        const mpHeight = hasMp ? 3 : 0;
        const gap = hasMp ? 2 : 0;

        const contentH = hpHeight + gap + mpHeight;
        const totalW = contentW + BAR_PADDING * 2;
        const totalH = contentH + BAR_PADDING * 2;

        const startX = x - totalW / 2;
        const startY = y - 5; 

        // Container
        ctx.save();
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(startX, startY, totalW, totalH, 6);
        else ctx.rect(startX, startY, totalW, totalH);

        // Dark Glass BG
        ctx.fillStyle = 'rgba(2, 6, 23, 0.7)'; 
        ctx.fill();

        // Team-colored Border Highlight
        const teamBorder = agent.team === Team.BLUE ? '#3b82f6' : '#ef4444';
        ctx.lineWidth = 1;
        ctx.strokeStyle = isSelected ? teamBorder : 'rgba(255, 255, 255, 0.15)';
        ctx.stroke();

        // Optimized: Remove ShadowBlur for performance
        if (isSelected) {
            ctx.lineWidth = 2;
            ctx.stroke();
        }
        ctx.restore();

        const barX = startX + BAR_PADDING;
        const barY = startY + BAR_PADDING;

        // HP Bar - Faction Colored
        const hpPct = Math.max(0, agent.hp / agent.maxHp);
        let hpTop, hpBot;

        if (agent.team === Team.BLUE) {
            // IMPERIAL CYAN/BLUE
            hpTop = '#22d3ee';
            hpBot = '#0284c7';
        } else {
            // COVENANT RED/ORANGE
            hpTop = '#f87171';
            hpBot = '#dc2626';
        }

        this.drawFluidBar(ctx, barX, barY, contentW, hpHeight, hpPct, hpTop, hpBot);

        // MP Bar - Always Blue/Purple
        if (hasMp) {
            const mpPct = Math.max(0, agent.mp / agent.maxMp);
            const mpY = barY + hpHeight + gap;
            this.drawFluidBar(ctx, barX, mpY, contentW, mpHeight, mpPct, '#a78bfa', '#7c3aed');
        }
    }

    private drawFluidBar(ctx: CanvasRenderingContext2D, bx: number, by: number, bw: number, bh: number, pct: number, colTop: string, colBot: string) {
        if (pct <= 0.01) return;
        const fillW = Math.max(bh, bw * pct); 

        ctx.save();
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(bx, by, fillW, bh, bh/2);
        else ctx.rect(bx, by, fillW, bh);

        const grad = ctx.createLinearGradient(bx, by, bx, by + bh);
        grad.addColorStop(0, colTop);
        grad.addColorStop(1, colBot);
        ctx.fillStyle = grad;

        // Optimized: Removed shadowBlur
        ctx.fill();

        // Gloss
        ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(bx, by, fillW, bh * 0.4, bh/2);
        else ctx.rect(bx, by, fillW, bh * 0.4);
        ctx.fill();

        ctx.restore();
    }

    private drawCircularGauge(ctx: CanvasRenderingContext2D, x: number, y: number, pct: number, visualKey: string, color: string, isSkill: boolean) {
        const radius = 14;
        const iconY = y - 24; 

        ctx.save();
        ctx.beginPath();
        ctx.arc(x, iconY, radius, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(2, 6, 23, 0.8)';
        ctx.fill();
        ctx.save();
        ctx.clip();

        let icon;
        if (isSkill) {
            icon = AssetManager.getSkillIcon(visualKey, color);
        } else {
            icon = AssetManager.getStatusIcon(visualKey);
        }

        ctx.globalAlpha = 0.8;
        if (icon) ctx.drawImage(icon, x - radius, iconY - radius, radius * 2, radius * 2);
        ctx.restore();

        ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
        ctx.lineWidth = 2;
        ctx.stroke();

        const safePct = Math.max(0, Math.min(1, pct));
        if (safePct > 0) {
            ctx.beginPath();
            ctx.arc(x, iconY, radius, -Math.PI / 2, -Math.PI / 2 + (Math.PI * 2 * safePct));
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.lineCap = 'round';
            // Optimized: Removed shadowBlur
            ctx.stroke();
        }

        ctx.restore();
    }

    private drawFloatingText(ctx: CanvasRenderingContext2D) {
        this.damageNumbers.forEach(d => {
            if (!d.active) return;

            const lifePct = d.life / d.maxLife;
            const alpha = lifePct < 0.3 ? lifePct / 0.3 : 1.0;

            ctx.globalAlpha = alpha;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.shadowBlur = 0; 

            if (d.type === 'KILL_STREAK') {
                ctx.save();
                ctx.translate(d.x, d.y);
                const pop = Math.min(1, (1 - lifePct) * 5); 
                const pulse = 1 + Math.sin(lifePct * 10) * 0.1;
                const scale = pop * pulse * 1.5; 
                ctx.scale(scale, scale);
                ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;

                const grad = ctx.createLinearGradient(0, -d.size/2, 0, d.size/2);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.5, d.color);
                grad.addColorStop(1, '#000000');

                ctx.lineWidth = 4;
                ctx.lineJoin = 'round';
                ctx.strokeStyle = '#000';
                ctx.strokeText(d.text, 0, 0);
                ctx.fillStyle = grad;
                ctx.fillText(d.text, 0, 0);
                ctx.restore();

            } else if (d.type === 'SHOUT') {
                if (d.isUlt) {
                    const scale = 1 + (1 - lifePct) * 0.1; 
                    ctx.save();
                    ctx.translate(d.x, d.y);
                    ctx.scale(scale, scale);
                    ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;
                    const textMetrics = ctx.measureText(d.text);
                    const w = textMetrics.width / 2 + 25;
                    const h = d.size + 12;

                    const bgGrad = ctx.createLinearGradient(-w - 20, 0, w + 20, 0);
                    bgGrad.addColorStop(0, 'rgba(0,0,0,0)');
                    bgGrad.addColorStop(0.3, 'rgba(2, 6, 23, 0.85)'); 
                    bgGrad.addColorStop(0.7, 'rgba(2, 6, 23, 0.85)');
                    bgGrad.addColorStop(1, 'rgba(0,0,0,0)');

                    ctx.fillStyle = bgGrad;
                    ctx.fillRect(-w - 20, -h/2, w*2 + 40, h);

                    ctx.strokeStyle = d.color;
                    ctx.lineWidth = 2;
                    ctx.globalAlpha = alpha * 0.8;

                    ctx.beginPath(); ctx.moveTo(-w, -h/2); ctx.lineTo(w, -h/2); ctx.stroke();
                    ctx.beginPath(); ctx.moveTo(-w * 0.8, h/2); ctx.lineTo(w * 0.8, h/2); ctx.stroke();

                    ctx.globalAlpha = alpha;
                    // Optimized: Reduced shadowBlur or remove if needed
                    ctx.shadowColor = d.color; ctx.shadowBlur = 0; 
                    ctx.fillStyle = '#fff';
                    ctx.fillText(d.text, 0, 0);
                    ctx.restore();
                } else {
                    ctx.font = `bold ${d.size}px "Segoe UI", sans-serif`;
                    const textMetrics = ctx.measureText(d.text);
                    const padX = 12;
                    const padY = 6;
                    const w = textMetrics.width;
                    const h = d.size;

                    ctx.fillStyle = 'rgba(15, 23, 42, 0.75)'; 
                    ctx.beginPath();
                    if (ctx.roundRect) ctx.roundRect(d.x - w/2 - padX, d.y - h/2 - padY, w + padX*2, h + padY*2, 8);
                    else ctx.rect(d.x - w/2 - padX, d.y - h/2 - padY, w + padX*2, h + padY*2);
                    ctx.fill();

                    ctx.strokeStyle = `rgba(255,255,255,0.15)`;
                    ctx.lineWidth = 1;
                    ctx.stroke();

                    // Optimized: Removed shadowBlur
                    ctx.fillStyle = '#fff'; 
                    ctx.fillText(d.text, d.x, d.y);
                }

            } else {
                // DAMAGE / HEAL / CC
                ctx.font = `900 ${d.size}px "Segoe UI", sans-serif`;

                // Outline to make it readable on any background
                ctx.lineWidth = 3;
                ctx.strokeStyle = 'rgba(0,0,0,0.8)';
                ctx.strokeText(d.text, d.x, d.y);

                ctx.fillStyle = d.color; 
                ctx.fillText(d.text, d.x, d.y);
            }

            ctx.globalAlpha = 1.0;
        });
    }
}

import { Agent } from "../../game";
import { AssetManager } from "../../assets";
import { Team } from "../../../types";
import { SurfaceAssets } from "../../graphics/SurfaceAssets";
import { HEX_SIZE } from "../../../constants";

// Helper to calculate animation progress (0.0 to 1.0)
// Moved here from utils.ts to reduce file count
export function getCastProgress(agent: Agent): number {
    if (agent.castingSkillIdx === -1) return 0;
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return 0;
    const raw = agent.castTimer / skill.cast;
    return Math.max(0, Math.min(1, 1 - raw)); 
}

// Helper: Local Hexagon Trace
function traceHex(ctx: CanvasRenderingContext2D, r: number) {
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
        const angle = i * Math.PI / 3;
        const x = r * Math.cos(angle);
        const y = r * Math.sin(angle);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
    }
    ctx.closePath();
}

export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const isBlue = agent.team === Team.BLUE;
    const color = isBlue ? '#60a5fa' : '#f87171';

    const feetX = Math.round(physX);
    const feetY = Math.round(physY - physZ); 

    ctx.save();
    ctx.translate(feetX, feetY); // Center at shadow point
    ctx.save();
    ctx.scale(1, 0.58); 
    ctx.lineDashOffset = -t * 20;
    ctx.globalAlpha = 0.6;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.setLineDash([8, 4]);
    traceHex(ctx, 18);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.restore();

    if (physZ > 5) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.3;
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(0, physZ); ctx.stroke(); // Vertical line from shadow to body
    }
    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const color = agent.team === Team.BLUE ? '#bae6fd' : '#fecaca'; 
    ctx.save();
    ctx.translate(0, 5); 
    ctx.scale(1, 0.5); 
    ctx.rotate(t * 8); 
    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.globalAlpha = 0.5 + Math.sin(t * 20) * 0.2; 
    // Hexagonal Thruster Ring
    traceHex(ctx, 15);
    ctx.stroke();
    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    // --- 1. HEXAGONAL ORBITAL BITS ---
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const orbitRadius = 25;
    for (let i = 0; i < 3; i++) {
        const offset = i * (Math.PI * 2 / 3);
        const ox = Math.round(Math.cos(t * 6 + offset) * orbitRadius);
        const oy = Math.round(Math.sin(t * 6 + offset) * orbitRadius * 0.5) - 35;

        ctx.save();
        ctx.translate(ox, oy);
        ctx.rotate(t * 10);
        ctx.beginPath();
        traceHex(ctx, 4 * progress); // Small Hex Bit
        ctx.fillStyle = '#fff';
        // PERF: Removed shadowBlur
        ctx.fill();
        ctx.restore();
    }
    ctx.restore();

    if (skill.type === 'AOE') {
        drawDomainExpansion(ctx, agent, t, color, progress);
    }
}

export function drawDomainExpansion(ctx: CanvasRenderingContext2D, agent: Agent, t: number, color: string, progress: number) {
    ctx.save();
    ctx.translate(0, -40); 
    const scale = 0.5 + progress * 0.5;
    ctx.scale(scale, scale * 0.5); 
    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.globalCompositeOperation = 'screen';
    ctx.rotate(t * 2);
    traceHex(ctx, 60);
    ctx.stroke();
    ctx.restore();
}

export function drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;
    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    ctx.translate(0, -40); 
    const size = Math.round(50 * (0.2 + progress * 0.8));
    ctx.globalCompositeOperation = 'screen';

    // Hexagonal Gradient Fill
    // We can't do radial gradient easily on a path, so we just use stacked hexes
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.3;
    traceHex(ctx, size); ctx.fill();

    ctx.fillStyle = '#fff';
    ctx.globalAlpha = 0.5;
    traceHex(ctx, size * 0.6); ctx.fill();

    ctx.restore();
}

export function drawSkillGroundIndicator(
    ctx: CanvasRenderingContext2D, 
    x: number, y: number, 
    color: string, 
    t: number, 
    progress: number, 
    skillRadius: number, 
    type: string, 
    isAOE: boolean
) {
    ctx.save();
    ctx.translate(Math.round(x), Math.round(y));

    // Calculate size
    const maxPx = Math.max(1, skillRadius) * HEX_SIZE;
    const currentRadius = maxPx * progress;

    ctx.scale(1, 0.58); // Isometric flatten

    // --- LAYER 1: BASE FIELD (Hex Fill) ---
    traceHex(ctx, currentRadius);
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.35; 
    ctx.fill();

    // --- LAYER 2: ENERGY RIM (Hex Glow) ---
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = color;
    ctx.lineWidth = 5;
    ctx.globalAlpha = 0.9;
    // PERF: Removed expensive shadowBlur, simulated with layers or alpha
    traceHex(ctx, currentRadius);
    ctx.stroke();

    // Fake Glow Layer (Cheaper)
    ctx.lineWidth = 2;
    ctx.strokeStyle = '#fff';
    ctx.globalAlpha = 0.4;
    traceHex(ctx, currentRadius + 2);
    ctx.stroke();

    ctx.restore();

    // --- LAYER 3: RUNIC BORDER (Rotating Hex) ---
    ctx.save();
    ctx.rotate(t * 1.5); 
    ctx.strokeStyle = '#fff'; 
    ctx.lineWidth = 2;
    ctx.setLineDash([10, 8]); // Dashed pattern
    ctx.globalAlpha = 0.8;
    traceHex(ctx, currentRadius + 2);
    ctx.stroke();
    ctx.restore();

    ctx.restore();
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill) {
            ctx.save();
            ctx.translate(0, Math.round(-110));

            // Hex Glow Background
            ctx.globalAlpha = 0.3 * (0.5 + Math.sin(t * 10) * 0.1);
            ctx.fillStyle = skill.color;
            traceHex(ctx, 40);
            ctx.fill();

            ctx.restore();
        }
    }
}

export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;
    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    if (agent.stunTimer > 0) {
        ctx.translate(0, Math.round(-65));
        const angle = t * 5;
        const x = Math.round(Math.cos(angle) * 20);
        const y = Math.round(Math.sin(angle) * 6); 
        ctx.fillStyle = '#facc15';

        // Spinning Star/Hex
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(t * 10);
        traceHex(ctx, 4);
        ctx.fill();
        ctx.restore();
    }
    ctx.restore();
}

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../UnitVisuals";
import { THEME_IMPERIAL } from "../../../../constants";

// Helper: Improved Ease for Disciplined Combat
function easeAttack(t: number): number {
    if (t < 0.3) {
        const p = t / 0.3;
        return -0.25 * (p * p); 
    } else if (t < 0.45) {
        const p = (t - 0.3) / 0.15;
        return -0.25 + (1.35 * (p * p * p)); 
    } else {
        const p = (t - 0.45) / 0.55;
        return 1.1 * Math.cos(p * Math.PI / 2);
    }
}

export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = THEME_IMPERIAL.energy; 

        // 1. IDLE & BREATHING
        const breathePhase = t * 2.0;
        const floatY = (agent.hp > 0) ? Math.sin(breathePhase) * 2.5 : 0;
        const breatheScale = (agent.hp > 0) ? 1.0 + Math.sin(breathePhase) * 0.02 : 1.0;

        // 2. HIT REACTION
        let hitShakeRot = 0;
        let hitSquashX = 1.0;
        let hitSquashY = 1.0;

        if (agent.hitFlashTimer > 0) {
            hitShakeRot = (Math.random() - 0.5) * 0.15; 
            const trauma = agent.hitFlashTimer * 5; 
            hitSquashY = 1.0 - (trauma * 0.15);
            hitSquashX = 1.0 + (trauma * 0.1);
        }

        // 3. ATTACK ANIMATION
        let armRot = 0;
        let armX = 0;
        let armY = 0;
        let bodyRecoilX = 0;
        let bodyRecoilY = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const p = getCastProgress(agent);
            const curve = easeAttack(p);

            if (agent.role === Role.RANGER || agent.role === Role.MAGE) {
                const kick = Math.max(0, curve);
                armX = kick * 12;
                if (p > 0.3 && p < 0.6) bodyRecoilX = -4 * kick;
                if (p < 0.3) armRot = -0.3 * (p/0.3); 
            } else {
                armRot = curve * (Math.PI / 1.6); 
                if (curve > 0.5) {
                    armX = 18 * curve;
                    bodyRecoilX = 5 * curve; 
                } else if (curve < 0) {
                    bodyRecoilX = -2;
                }
            }
        }

        ctx.save();

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.translate(bodyRecoilX, floatY);
            ctx.strokeRect(-15, -60, 30, 60);
            ctx.restore();
            return;
        }

        ctx.translate(bodyRecoilX, floatY + bodyRecoilY);
        ctx.translate(0, -40); 
        ctx.rotate(hitShakeRot);
        ctx.scale(breatheScale * hitSquashX, breatheScale * hitSquashY);
        ctx.translate(0, 40);

        drawCape(ctx, t, THEME_IMPERIAL.cape, bodyRecoilX);

        ctx.save();
        ctx.translate(-20, -35);
        ctx.translate(0, Math.sin(t * 2.5 + Math.PI) * 2); 
        if (agent.role === Role.TANK) drawImperialShield(ctx);
        else if (agent.role === Role.SUPPORT || agent.role === Role.MAGE) drawImperialTome(ctx, t);
        ctx.restore();

        drawImperialBody(ctx, agent.role);

        ctx.save();
        ctx.translate(20, -35);
        ctx.rotate(armRot);
        ctx.translate(armX, armY);
        drawImperialWeapon(ctx, agent.role, t);
        ctx.restore();

        ctx.restore();
    }
};

function drawImperialBody(ctx: CanvasRenderingContext2D, role: Role) {
    const { primary, secondary, armorLight, armorDark } = THEME_IMPERIAL;

    const grad = ctx.createLinearGradient(-15, -50, 15, 0);
    grad.addColorStop(0, armorLight);
    grad.addColorStop(0.5, armorDark);
    grad.addColorStop(1, primary);

    ctx.fillStyle = grad;
    ctx.strokeStyle = secondary;
    ctx.lineWidth = 1.5;

    ctx.beginPath();
    if (role === Role.TANK) {
        ctx.moveTo(-22, -45); ctx.lineTo(22, -45);
        ctx.lineTo(15, 0); ctx.lineTo(-15, 0);
        ctx.lineTo(-22, -45);
    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        ctx.moveTo(-12, -45); ctx.lineTo(12, -45);
        ctx.lineTo(18, 10); ctx.lineTo(-18, 10);
        ctx.lineTo(-12, -45);
    } else {
        ctx.moveTo(-18, -45); ctx.lineTo(18, -45);
        ctx.lineTo(12, 5); ctx.lineTo(-12, 5);
        ctx.lineTo(-18, -45);
    }
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = '#fff';
    ctx.beginPath(); ctx.moveTo(0, -35); ctx.lineTo(6, -25); ctx.lineTo(0, -15); ctx.lineTo(-6, -25); ctx.fill();

    ctx.save();
    ctx.translate(0, -50);

    if (role === Role.MAGE || role === Role.SUPPORT) {
        ctx.strokeStyle = secondary;
        ctx.beginPath(); ctx.arc(0, -5, 16, 0, Math.PI*2); ctx.stroke();
    }

    ctx.fillStyle = armorLight;
    ctx.strokeStyle = secondary;
    ctx.lineWidth = 1;
    ctx.beginPath();
    if (role === Role.TANK) ctx.rect(-10, -12, 20, 18); 
    else ctx.ellipse(0, -2, 9, 11, 0, 0, Math.PI*2);
    ctx.fill(); ctx.stroke();

    ctx.fillStyle = primary;
    ctx.fillRect(-8, -4, 16, 3);

    ctx.restore();
}

function drawCape(ctx: CanvasRenderingContext2D, t: number, color: string, speedX: number) {
    ctx.save();
    ctx.translate(0, -45);
    const drag = -speedX * 1.5;
    const wave = Math.sin(t * 3) * 3;

    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(-10, 0);
    ctx.lineTo(-15 + wave + drag, 50);
    ctx.lineTo(15 + wave + drag, 50);
    ctx.lineTo(10, 0);
    ctx.fill();
    ctx.restore();
}

function drawImperialHand(ctx: CanvasRenderingContext2D) {
    ctx.fillStyle = THEME_IMPERIAL.armorDark;
    ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = THEME_IMPERIAL.secondary;
    ctx.beginPath(); ctx.arc(0, 0, 4, 0, Math.PI*2); ctx.fill();
}

function drawImperialShield(ctx: CanvasRenderingContext2D) {
    drawImperialHand(ctx);
    ctx.translate(-5, 10);
    ctx.rotate(-Math.PI/12);

    const grad = ctx.createLinearGradient(0, -30, 0, 30);
    grad.addColorStop(0, THEME_IMPERIAL.armorLight);
    grad.addColorStop(1, THEME_IMPERIAL.primary);

    ctx.fillStyle = grad;
    ctx.strokeStyle = THEME_IMPERIAL.secondary;
    ctx.lineWidth = 3;

    ctx.beginPath();
    ctx.moveTo(-15, -30); ctx.lineTo(15, -30);
    ctx.lineTo(15, 10); ctx.lineTo(0, 40); ctx.lineTo(-15, 10);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = THEME_IMPERIAL.energy;
    ctx.fillRect(-5, -20, 10, 40);
    ctx.fillRect(-12, -5, 24, 10);
}

function drawImperialTome(ctx: CanvasRenderingContext2D, t: number) {
    drawImperialHand(ctx);
    ctx.translate(0, -10);
    ctx.fillStyle = '#fff';
    ctx.fillRect(-10, -12, 20, 24); 
    ctx.fillStyle = THEME_IMPERIAL.primary;
    ctx.fillRect(-12, -12, 4, 24); 

    if (Math.sin(t*5) > 0) {
        ctx.fillStyle = THEME_IMPERIAL.secondary;
        ctx.fillRect(5, -20, 2, 2);
        ctx.fillRect(8, -25, 2, 2);
    }
}

function drawImperialWeapon(ctx: CanvasRenderingContext2D, role: Role, t: number) {
    drawImperialHand(ctx);

    if (role === Role.WARRIOR) {
        ctx.rotate(Math.PI / 4); // Adjusted to 45 degrees for better idle stance
        ctx.fillStyle = '#475569';
        ctx.fillRect(-4, -10, 8, 20); 
        ctx.fillStyle = THEME_IMPERIAL.secondary;
        ctx.fillRect(-12, -10, 24, 4); 
        ctx.fillStyle = 'rgba(147, 197, 253, 0.8)';
        ctx.strokeStyle = THEME_IMPERIAL.primary;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-6, -10); ctx.lineTo(-4, -70); ctx.lineTo(0, -80);
        ctx.lineTo(4, -70); ctx.lineTo(6, -10);
        ctx.fill(); ctx.stroke();

    } else if (role === Role.TANK) {
        ctx.rotate(Math.PI / 3);
        ctx.fillStyle = '#475569';
        ctx.fillRect(-3, -10, 6, 50);
        ctx.translate(0, -50);
        ctx.fillStyle = THEME_IMPERIAL.armorLight;
        ctx.strokeStyle = THEME_IMPERIAL.secondary;
        ctx.lineWidth = 2;
        ctx.fillRect(-12, -15, 24, 30);
        ctx.strokeRect(-12, -15, 24, 30);
        ctx.fillStyle = THEME_IMPERIAL.primary;
        ctx.beginPath(); ctx.moveTo(0, -15); ctx.lineTo(-20, 0); ctx.lineTo(0, 15); ctx.fill();
        ctx.beginPath(); ctx.moveTo(0, -15); ctx.lineTo(20, 0); ctx.lineTo(0, 15); ctx.fill();

    } else if (role === Role.RANGER) {
        ctx.translate(10, 0);
        ctx.strokeStyle = THEME_IMPERIAL.armorLight;
        ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(0, 0, 30, -Math.PI/2 - 0.5, Math.PI/2 + 0.5); ctx.stroke();
        ctx.strokeStyle = THEME_IMPERIAL.energy; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(0, -30); ctx.lineTo(0, 30); ctx.stroke();

    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        ctx.rotate(-Math.PI / 6);
        ctx.fillStyle = '#b45309';
        ctx.fillRect(-3, -40, 6, 80);
        ctx.translate(0, -45);
        const float = Math.sin(t * 4) * 3;
        ctx.translate(0, float);
        ctx.fillStyle = role === Role.MAGE ? THEME_IMPERIAL.energy : THEME_IMPERIAL.secondary;
        ctx.beginPath(); ctx.moveTo(0, -10); ctx.lineTo(8, 0); ctx.lineTo(0, 10); ctx.lineTo(-8, 0); ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.arc(0, 0, 14, 0, Math.PI*2); ctx.stroke();
    }
}

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../UnitVisuals";
import { THEME_COVENANT } from "../../../../constants";

function easeAttack(t: number): number {
    if (t < 0.45) {
        const p = t / 0.45;
        return -0.5 * (p * p * p); 
    } else if (t < 0.55) {
        const p = (t - 0.45) / 0.1;
        return -0.5 + (1.7 * p); 
    } else {
        const p = (t - 0.55) / 0.45;
        return 1.2 - (1.2 * p) + Math.sin(p * Math.PI * 2) * 0.1;
    }
}

export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = THEME_COVENANT.secondary; 

        // 1. IDLE & BREATHING
        const noise = Math.sin(t * 7.0) * 0.5 + Math.sin(t * 3.0);
        const floatY = (agent.hp > 0) ? noise * 1.5 : 0;

        const breatheScaleX = (agent.hp > 0) ? 1.0 + Math.sin(t * 4.0) * 0.03 : 1.0;
        const breatheScaleY = (agent.hp > 0) ? 1.0 - Math.sin(t * 4.0) * 0.02 : 1.0;

        // 2. HIT REACTION
        let hitShakeX = 0;
        let hitShakeRot = 0;
        let hitSquashY = 1.0;

        if (agent.hitFlashTimer > 0) {
            hitShakeX = (Math.random() - 0.5) * 4.0;
            hitShakeRot = (Math.random() - 0.5) * 0.3;
            const trauma = agent.hitFlashTimer * 5;
            hitSquashY = 1.0 - (trauma * 0.2); 
        }

        // 3. ATTACK ANIMATION
        let armRot = 0;
        let armX = 0;
        let armY = 0;
        let bodyRecoilX = 0;
        let bodyRecoilY = 0;
        let bodyRot = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const p = getCastProgress(agent);
            const curve = easeAttack(p);

            if (agent.role === Role.RANGER || agent.role === Role.MAGE) {
                const jerk = Math.max(0, curve);
                armX = jerk * 25; 
                if (p > 0.4 && p < 0.6) {
                    bodyRecoilX = -8; 
                    bodyRecoilY = (Math.random() - 0.5) * 4;
                }
            } else {
                armRot = curve * (Math.PI / 1.3);
                if (curve > 0) {
                    armX = 25 * curve;
                    armY = 15 * curve; 
                    bodyRecoilX = 10 * curve; 
                    bodyRot = 0.1 * curve; 
                } else {
                    bodyRecoilX = -5; 
                    bodyRot = -0.1;   
                }
            }
        }

        ctx.save();

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.translate(bodyRecoilX, floatY);
            ctx.beginPath();
            ctx.moveTo(-15, -60); ctx.lineTo(0, -70); ctx.lineTo(15, -60);
            ctx.lineTo(10, 0); ctx.lineTo(-10, 0); ctx.closePath();
            ctx.stroke();
            ctx.restore();
            return;
        }

        ctx.translate(bodyRecoilX + hitShakeX, floatY + bodyRecoilY);
        ctx.translate(0, -40); 
        ctx.rotate(hitShakeRot + bodyRot);
        ctx.scale(breatheScaleX, breatheScaleY * hitSquashY);
        ctx.translate(0, 40);

        drawSpikes(ctx, t);

        ctx.save();
        ctx.translate(-22, -30);
        ctx.translate(0, Math.sin(t * 3) * 2);
        if (agent.role === Role.TANK) drawCovenantShield(ctx);
        else if (agent.role === Role.SUPPORT || agent.role === Role.MAGE) drawCovenantTotem(ctx, t);
        ctx.restore();

        drawCovenantBody(ctx, agent.role);

        ctx.save();
        ctx.translate(22, -30); // Shoulder
        ctx.rotate(armRot);
        ctx.translate(armX, armY);
        drawCovenantWeapon(ctx, agent.role, t);
        ctx.restore();

        ctx.restore();
    }
};

function drawCovenantBody(ctx: CanvasRenderingContext2D, role: Role) {
    const { primary, armorDark, armorBase, accent, secondary } = THEME_COVENANT;

    const grad = ctx.createLinearGradient(-15, -50, 15, 10);
    grad.addColorStop(0, primary);
    grad.addColorStop(0.6, armorDark);
    grad.addColorStop(1, '#000');

    ctx.fillStyle = grad;
    ctx.strokeStyle = accent;
    ctx.lineWidth = 1;

    ctx.beginPath();
    if (role === Role.TANK) {
        ctx.moveTo(-25, -40); ctx.lineTo(25, -40); 
        ctx.lineTo(15, 10); ctx.lineTo(-15, 10);
        ctx.lineTo(-25, -40);
    } else {
        ctx.moveTo(-18, -45); ctx.lineTo(18, -45);
        ctx.lineTo(8, 15); ctx.lineTo(-8, 15);
        ctx.lineTo(-18, -45);
    }
    ctx.fill();
    ctx.stroke();

    ctx.strokeStyle = secondary;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, -35);
    ctx.lineTo((Math.random()-0.5)*5, -25);
    ctx.lineTo(0, -15);
    ctx.stroke();

    ctx.save();
    ctx.translate(0, -48);

    ctx.fillStyle = armorDark;
    ctx.beginPath();
    ctx.moveTo(-10, 5); ctx.lineTo(-12, -15); ctx.lineTo(-5, -5); 
    ctx.lineTo(5, -5); ctx.lineTo(12, -15); ctx.lineTo(10, 5);
    ctx.fill();

    ctx.fillStyle = '#fca5a5';
    ctx.beginPath(); ctx.arc(0, 0, 3, 0, Math.PI*2); ctx.fill();

    ctx.restore();
}

function drawSpikes(ctx: CanvasRenderingContext2D, t: number) {
    ctx.save();
    ctx.translate(0, -40);
    ctx.fillStyle = THEME_COVENANT.spike;
    ctx.beginPath();
    ctx.moveTo(-10, 0); ctx.lineTo(-25, -30 + Math.sin(t*5)*2); ctx.lineTo(-15, 0);
    ctx.moveTo(10, 0); ctx.lineTo(20, -25 + Math.cos(t*4)*2); ctx.lineTo(15, 0);
    ctx.fill();
    ctx.restore();
}

function drawCovenantHand(ctx: CanvasRenderingContext2D) {
    ctx.fillStyle = THEME_COVENANT.armorDark;
    ctx.beginPath(); 
    ctx.moveTo(-6, -6); ctx.lineTo(6, -6); ctx.lineTo(4, 8); ctx.lineTo(-4, 8);
    ctx.fill();
}

function drawCovenantShield(ctx: CanvasRenderingContext2D) {
    drawCovenantHand(ctx);
    ctx.translate(-5, 10);

    ctx.fillStyle = THEME_COVENANT.armorBase;
    ctx.strokeStyle = THEME_COVENANT.secondary;
    ctx.lineWidth = 2;

    ctx.beginPath();
    ctx.moveTo(-15, -25); ctx.lineTo(15, -20);
    ctx.lineTo(20, 0); ctx.lineTo(10, 25);
    ctx.lineTo(-15, 20); ctx.lineTo(-20, 0);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = THEME_COVENANT.accent;
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(0, -35); ctx.lineTo(5, -10); ctx.fill();
}

function drawCovenantTotem(ctx: CanvasRenderingContext2D, t: number) {
    drawCovenantHand(ctx);
    ctx.translate(0, 10);
    ctx.fillStyle = '#3f3f46';
    ctx.fillRect(-4, -40, 8, 50);
    ctx.translate(0, -45);
    ctx.fillStyle = THEME_COVENANT.secondary;
    ctx.beginPath();
    ctx.moveTo(-8, 0); ctx.lineTo(0, -10); ctx.lineTo(8, 0); ctx.lineTo(0, 10);
    ctx.fill();
}

function drawCovenantWeapon(ctx: CanvasRenderingContext2D, role: Role, t: number) {
    drawCovenantHand(ctx);

    if (role === Role.WARRIOR) {
        ctx.rotate(Math.PI / 4);
        ctx.fillStyle = THEME_COVENANT.armorBase;
        ctx.fillRect(-3, -10, 6, 60);
        ctx.translate(0, -60);
        ctx.fillStyle = '#52525b';
        ctx.strokeStyle = THEME_COVENANT.secondary;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(0, 0); ctx.lineTo(-25, -10);
        ctx.quadraticCurveTo(-15, 10, -25, 30);
        ctx.lineTo(0, 20);
        ctx.fill(); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(10, 5); ctx.lineTo(0, 10); ctx.fill();

    } else if (role === Role.TANK) {
        ctx.rotate(Math.PI / 3);
        ctx.fillStyle = THEME_COVENANT.armorBase;
        ctx.fillRect(-4, -5, 8, 20);
        ctx.fillStyle = THEME_COVENANT.accent;
        ctx.beginPath();
        ctx.moveTo(-10, -10); ctx.lineTo(-10, -60);
        ctx.lineTo(20, -60); ctx.lineTo(20, -10); ctx.lineTo(0, 0);
        ctx.fill();
        ctx.strokeStyle = THEME_COVENANT.secondary; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(20, -60); ctx.lineTo(20, -10); ctx.stroke();

    } else if (role === Role.RANGER) {
        ctx.rotate(-Math.PI / 2);
        ctx.fillStyle = THEME_COVENANT.armorDark;
        ctx.fillRect(-5, -30, 10, 40);
        ctx.strokeStyle = THEME_COVENANT.accent; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.moveTo(-25, -25); ctx.lineTo(0, -30); ctx.lineTo(25, -25); ctx.stroke();
        ctx.strokeStyle = '#52525b'; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(-25, -25); ctx.lineTo(0, 0); ctx.lineTo(25, -25); ctx.stroke();

    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        ctx.rotate(Math.PI / 6);
        ctx.fillStyle = '#450a0a';
        ctx.beginPath(); ctx.moveTo(0, 10); ctx.lineTo(-5, -30); ctx.lineTo(0, -50); ctx.lineTo(5, -30); ctx.fill();
        ctx.fillStyle = THEME_COVENANT.secondary;
        ctx.beginPath(); ctx.arc(0, -50, 3, 0, Math.PI*2); ctx.fill();
    }
}

export enum Team {
    BLUE = 0,
    RED = 1
}

export enum Role {
    TANK = 'TANK',
    WARRIOR = 'WARRIOR',
    RANGER = 'RANGER',
    MAGE = 'MAGE',
    SUPPORT = 'SUPPORT'
}

export enum MovementType {
    GROUND = 0,
    FLYING = 1
}

export enum AnimState {
    IDLE = 0,
    COMBAT_IDLE = 1,
    ATTACK = 2,
    HIT = 3,
    DEAD = 4,
    STUN = 5,
    MOVE = 6
}

export interface Hex {
    q: number;
    r: number;
}

export interface Point {
    x: number;
    y: number;
}

// Scene / Environment Types
export interface SceneTheme {
    id: string;
    name: string;
    background: string; // Sky Top Color
    horizon: string;    // Sky Bottom/Horizon Color (New)
    fogColor: string;   // Low-lying fog color (New)
    textureType: 'VOID' | 'FOREST' | 'ICE' | 'MAGMA' | 'DESERT';
    obstacleStyle: string; 
    hexStroke: string; 
    ambientType: 'NONE' | 'SNOW' | 'ASH' | 'SPORES' | 'RAIN' | 'EMBER';
    ambientColor: string;
    bgFeature: 'NONE' | 'SKY_RIVER' | 'AURORA' | 'CANOPY' | 'HEAT_WAVE' | 'DUNES';
}

// Data Models
export interface Skill {
    id: string;
    tag: 'BASIC' | 'ACTIVE' | 'ULT';
    role: Role;
    team?: Team; // Optional: If specified, only this team can learn it
    name: string;
    desc?: string; // For Tooltips
    range: number;
    cast: number;
    cd: number;
    cost: number;
    gain: number;
    type: 'SINGLE' | 'AOE';
    aoeRadius?: number; // Default 1 if not specified
    power: number;
    color: string;

    // Control Effects (Slot 1)
    ccType?: 'STUN' | 'BANISH' | 'KNOCKBACK' | 'PULL' | 'DOT' | 'HOT' | 'SILENCE';
    ccDur?: number;
    ccForce?: number;

    // Control Effects (Slot 2) - NEW: Allows composite effects like Knockback + Stun
    ccType2?: 'STUN' | 'BANISH' | 'KNOCKBACK' | 'PULL' | 'DOT' | 'HOT' | 'SILENCE';
    ccDur2?: number;
    ccForce2?: number;

    // Special Combat Effects (Slot 1)
    effectType?: 'VAMP' | 'MANA_BURN' | 'EXECUTE' | 'MANA_RESTORE';
    effectVal?: number; // e.g. 0.5 for 50% Vamp, 1.5 for 50% bonus Execute dmg

    // Special Combat Effects (Slot 2)
    effectType2?: 'VAMP' | 'MANA_BURN' | 'EXECUTE' | 'MANA_RESTORE';
    effectVal2?: number;

    projectileSpeed?: number; // 0 = Instant
    visual?: 'ARROW' | 'FIREBALL' | 'BOLT' | 'SLASH' | 'SMASH' | 'BEAM' | 'BOMB';
}

export interface UnitStats {
    role: Role;
    maxHp: number;
    maxMp: number;
    moveSpeed: number; // Tiles per second. 1.0 = 1 tile/sec
    movementType: MovementType; // Ground or Flying
}

export interface ObstacleDef {
    id: string;
    name: string;
    blocksVision: boolean;
    blocksMovement: boolean;
    blocksFlying?: boolean; // New: If true, blocks even flying units (High Towers/Pillars)
}

// Logic State Types
export enum NodeState {
    SUCCESS = 'S',
    FAILURE = 'F',
    RUNNING = 'R'
}

export type LogActionType = 'MOVE' | 'CAST' | 'HIT' | 'DECISION' | 'DEATH' | 'SYSTEM' | 'HEAL' | 'CC';

export interface LogEntry {
    id: string;
    time: string;
    turn: number; // Battle tick or frame count
    agentId: string; // "Who"
    team: Team | undefined;
    location: string; // "Where" (e.g., "(10, 5)")
    actionType: LogActionType;
    actionName: string; // "What" (e.g., "Fireball", "MoveTo")
    targetInfo?: string; // "To Whom" (e.g., "Tank-A @ (12,5)")
    detail: string; // Narrative details
    visualColor?: string; // For UI highlighting
}

export interface Projectile {
    id: string;
    x: number;
    y: number;
