export const LogTab: React.FC<LogTabProps> = ({ engine }) => {
    const [localLogs, setLocalLogs] = useState<LogEntry[]>([]);
    const endRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const interval = setInterval(() => {
            if (engine.logs.length !== localLogs.length) {
                setLocalLogs(engine.logs.slice(-100)); // Keep last 100
            }
        }, 200);
        return () => clearInterval(interval);
    }, [engine, localLogs.length]);

    // Auto-scroll to bottom on new logs (if near bottom)
    useEffect(() => {
        endRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [localLogs]);

    const downloadLogs = () => {
        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(engine.logs, null, 2));
        const anchor = document.createElement('a');
        anchor.setAttribute("href", dataStr);
        anchor.setAttribute("download", `battle_logs_${Date.now()}.json`);
        anchor.click();
    };

    return (
        <div className="flex flex-col h-full bg-transparent">
            {/* Control Header */}
            <div className="flex justify-between items-center p-5 border-b border-white/5 shrink-0">
                <div className="flex items-center gap-3">
                    <div className="relative">
                        <span className="w-2 h-2 rounded-full bg-emerald-500 absolute animate-ping opacity-75"></span>
                        <span className="w-2 h-2 rounded-full bg-emerald-500 relative block shadow-[0_0_8px_rgba(16,185,129,0.5)]"></span>
                    </div>
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em]">Data Stream</span>
                </div>
                <button 
                    onClick={downloadLogs} 
                    className="liquid-btn px-3 py-1.5 !text-[10px] !rounded-lg border-white/10 text-slate-400 hover:text-white hover:border-cyan-500/30"
                >
                    <Icons.Save className="w-3 h-3 mr-1.5" /> EXPORT
                </button>
            </div>

            {/* Log Stream */}
            <div className="flex-1 overflow-y-auto custom-scrollbar px-4 py-4 space-y-1 relative">
                {localLogs.length === 0 ? (
                    <div className="flex flex-col items-center justify-center h-40 opacity-30 gap-4 mt-10">
                        <div className="w-16 h-16 rounded-full border-2 border-dashed border-slate-600 animate-spin-slow"></div>
                        <span className="text-xs font-mono tracking-widest text-slate-500">AWAITING INPUT...</span>
                    </div>
                ) : (
                    localLogs.map(log => <LogItem key={log.id} log={log} />)
                )}
                <div ref={endRef} />
            </div>
        </div>
    );
};

import { Agent } from "../game";
import { COLORS, UNIT_VISUAL_HEIGHT, HUD_PADDING } from "../../constants";
import { HexUtils, MapConfig } from "../utils";
import { AssetManager } from "../assets";
import { Team } from "../../types";

// --- Constants ---
const GRAVITY = 200;
const TEXT_LIFESPAN = 1.0;
const BAR_WIDTH = 44;
const BAR_HEIGHT = 6;
const BAR_PADDING = 3;

interface FloatingText {
    active: boolean;
    x: number; 
    y: number;
    vx: number; 
    vy: number;
    text: string; 
    color: string;
    life: number; 
    maxLife: number;
    size: number;
    type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK';
    isUlt: boolean; 
}

export class HUDSystem {
    // Active Texts
    damageNumbers: FloatingText[] = [];

    // Memory Pool
    private pool: FloatingText[] = [];

    constructor() {
        for(let i=0; i<50; i++) this.pool.push(this.createEmpty());
    }

    public reset() {
        for (const d of this.damageNumbers) {
            this.release(d);
        }
        this.damageNumbers.length = 0;
    }

    private createEmpty(): FloatingText {
        return {
            active: false,
            x: 0, y: 0, vx: 0, vy: 0,
            text: '', color: '#fff', life: 0, maxLife: 0, size: 0,
            type: 'DAMAGE', isUlt: false
        };
    }

    public addFloatingText(x: number, y: number, text: string, color: string, size: number, type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK' = 'DAMAGE', isUlt: boolean = false) {
        // Limit kill streaks to avoid screen clutter if too many
        if (type === 'KILL_STREAK') {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                if (this.damageNumbers[i].type === 'KILL_STREAK') {
                    this.release(this.damageNumbers[i]);
                    // Swap and pop
                    this.damageNumbers[i] = this.damageNumbers[this.damageNumbers.length - 1];
                    this.damageNumbers.pop();
                }
            }
        }

        let vx = 0;
        let vy = 0;
        let life = TEXT_LIFESPAN;

        if (type === 'SHOUT') {
            if (isUlt) {
                vy = -5; 
                life = 2.5; 
                size = 24; 
            } else {
                vy = -20; 
                life = 1.2;
                size = 14; 
            }
        } else if (type === 'CC') {
            vy = -20; 
            life = 1.5;
        } else if (type === 'KILL_STREAK') {
            vx = 0;
            vy = -30;
            life = 3.5; 
            size = 32; 
        } else {
            vx = (Math.random() - 0.5) * 60; 
            vy = -100; 
        }

        let ft: FloatingText;
        if (this.pool.length > 0) {
            ft = this.pool.pop()!;
        } else {
            ft = this.createEmpty();
        }

        ft.active = true;
        ft.x = x; ft.y = y;
        ft.vx = vx; ft.vy = vy;
        ft.text = text; ft.color = color;
        ft.life = life; ft.maxLife = life;
        ft.size = size; ft.type = type;
        ft.isUlt = isUlt;

        this.damageNumbers.push(ft);
    }

    private release(ft: FloatingText) {
        ft.active = false;
        this.pool.push(ft);
    }

    update(dt: number) {
        const count = this.damageNumbers.length;
        // Iterate backwards for safe removal
        for (let i = count - 1; i >= 0; i--) { 
            const d = this.damageNumbers[i]; 
            d.life -= dt; 

            d.x += d.vx * dt;
            d.y += d.vy * dt; 

            if (d.type === 'DAMAGE' || d.type === 'HEAL') {
                d.vy += GRAVITY * dt;
            } else if (d.type === 'SHOUT' || d.type === 'CC') {
                d.vy *= 0.95; 
            } else if (d.type === 'KILL_STREAK') {
                d.vy *= 0.92; 
            }

            if (d.life <= 0) {
                this.release(d);
                // PERFORMANCE FIX: Swap-and-pop instead of splice(i,1)
                this.damageNumbers[i] = this.damageNumbers[this.damageNumbers.length - 1];
                this.damageNumbers.pop();
            }
        }
    }

    draw(ctx: CanvasRenderingContext2D, agents: Agent[], getTerrainHeight: (q: number, r: number) => number, mapConfig: MapConfig, highlight: Agent | null, time: number) {
        agents.forEach(a => {
            if (a.hp <= 0) return;
            if (a.spawnTimer > 0) return; 

            let h = 0;
            if (a.isMoving && a.path.length > 0) {
                const startH = getTerrainHeight(a.q, a.r);
                const endHex = a.path[0];
                const endH = getTerrainHeight(endHex.q, endHex.r);
                h = HexUtils.lerp(startH, endH, a.moveProgress);
            } else {
                const visualHex = HexUtils.fromPx(a.px, a.py, mapConfig);
                h = getTerrainHeight(visualHex.q, visualHex.r);
            }

            const groundY = a.py - h;
            const physicsOffsetY = a.physics.y - a.physics.z; 
            const anchorY = groundY - UNIT_VISUAL_HEIGHT + physicsOffsetY - HUD_PADDING;
            const headX = a.px + a.physics.x;

            const isSelected = (a === highlight);
            this.drawUnitBars(ctx, a, headX, anchorY, isSelected, time);
            this.drawUnitStatusGauges(ctx, a, headX, anchorY);
        });

        this.drawFloatingText(ctx);
    }

    private drawUnitStatusGauges(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number) {
        let activeTimer = 0;
        let maxTimer = 0;
        let iconType = '';
        let gaugeColor = '';

        if (agent.banished) {
            activeTimer = agent.banishTimer;
            maxTimer = agent.banishMax || activeTimer;

            if (agent.visualStatus === 'POLYMORPH') {
                iconType = 'POLYMORPH'; gaugeColor = '#d8b4fe';
            } else if (agent.visualStatus === 'STASIS') {
                iconType = 'STASIS'; gaugeColor = '#facc15';
            } else {
                iconType = 'BANISH'; gaugeColor = '#7e22ce';
            }
        } else if (agent.stunTimer > 0) {
            activeTimer = agent.stunTimer;
            maxTimer = agent.stunMax || activeTimer;
            iconType = 'STUN'; gaugeColor = '#fbbf24';
        } else if (agent.silenceTimer > 0) {
            activeTimer = agent.silenceTimer;
            maxTimer = agent.silenceMax || activeTimer;
            iconType = 'SILENCE'; gaugeColor = '#94a3b8';
        } else if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const progress = 1 - (agent.castTimer / skill.cast);
                this.drawCircularGauge(ctx, x, y, progress, skill.visual || 'BOLT', skill.color, true);
                return;
            }
        }

        if (iconType && maxTimer > 0) {
            const progress = activeTimer / maxTimer;
            this.drawCircularGauge(ctx, x, y, progress, iconType, gaugeColor, false);
        }
    }

    // 1. FACTION-BASED HP BARS REFACTOR
    private drawUnitBars(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, isSelected: boolean, time: number) {
        const hasMp = agent.maxMp > 0;

        const contentW = BAR_WIDTH;
        const hpHeight = BAR_HEIGHT;
        const mpHeight = hasMp ? 3 : 0;
        const gap = hasMp ? 2 : 0;

        const contentH = hpHeight + gap + mpHeight;
        const totalW = contentW + BAR_PADDING * 2;
        const totalH = contentH + BAR_PADDING * 2;

        const startX = x - totalW / 2;
        const startY = y - 5; 

        // Container
        ctx.save();
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(startX, startY, totalW, totalH, 6);
        else ctx.rect(startX, startY, totalW, totalH);

        // Dark Glass BG
        ctx.fillStyle = 'rgba(2, 6, 23, 0.7)'; 
        ctx.fill();

        // Team-colored Border Highlight
        const teamBorder = agent.team === Team.BLUE ? '#3b82f6' : '#ef4444';
        ctx.lineWidth = 1;
        ctx.strokeStyle = isSelected ? teamBorder : 'rgba(255, 255, 255, 0.15)';
        ctx.stroke();

        // Optimized: Remove ShadowBlur for performance
        if (isSelected) {
            ctx.lineWidth = 2;
            ctx.stroke();
        }
        ctx.restore();

        const barX = startX + BAR_PADDING;
        const barY = startY + BAR_PADDING;

        // HP Bar - Faction Colored
        const hpPct = Math.max(0, agent.hp / agent.maxHp);
        let hpTop, hpBot;

        if (agent.team === Team.BLUE) {
            // IMPERIAL CYAN/BLUE
            hpTop = '#22d3ee';
            hpBot = '#0284c7';
        } else {
            // COVENANT RED/ORANGE
            hpTop = '#f87171';
            hpBot = '#dc2626';
        }

        this.drawFluidBar(ctx, barX, barY, contentW, hpHeight, hpPct, hpTop, hpBot);

        // MP Bar - Always Blue/Purple
        if (hasMp) {
            const mpPct = Math.max(0, agent.mp / agent.maxMp);
            const mpY = barY + hpHeight + gap;
            this.drawFluidBar(ctx, barX, mpY, contentW, mpHeight, mpPct, '#a78bfa', '#7c3aed');
        }
    }

    private drawFluidBar(ctx: CanvasRenderingContext2D, bx: number, by: number, bw: number, bh: number, pct: number, colTop: string, colBot: string) {
        if (pct <= 0.01) return;
        const fillW = Math.max(bh, bw * pct); 

        ctx.save();
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(bx, by, fillW, bh, bh/2);
        else ctx.rect(bx, by, fillW, bh);

        const grad = ctx.createLinearGradient(bx, by, bx, by + bh);
        grad.addColorStop(0, colTop);
        grad.addColorStop(1, colBot);
        ctx.fillStyle = grad;

        // Optimized: Removed shadowBlur
        ctx.fill();

        // Gloss
        ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(bx, by, fillW, bh * 0.4, bh/2);
        else ctx.rect(bx, by, fillW, bh * 0.4);
        ctx.fill();

        ctx.restore();
    }

    private drawCircularGauge(ctx: CanvasRenderingContext2D, x: number, y: number, pct: number, visualKey: string, color: string, isSkill: boolean) {
        const radius = 14;
        const iconY = y - 24; 

        ctx.save();
        ctx.beginPath();
        ctx.arc(x, iconY, radius, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(2, 6, 23, 0.8)';
        ctx.fill();
        ctx.save();
        ctx.clip();

        let icon;
        if (isSkill) {
            icon = AssetManager.getSkillIcon(visualKey, color);
        } else {
            icon = AssetManager.getStatusIcon(visualKey);
        }

        ctx.globalAlpha = 0.8;
        if (icon) ctx.drawImage(icon, x - radius, iconY - radius, radius * 2, radius * 2);
        ctx.restore();

        ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
        ctx.lineWidth = 2;
        ctx.stroke();

        const safePct = Math.max(0, Math.min(1, pct));
        if (safePct > 0) {
            ctx.beginPath();
            ctx.arc(x, iconY, radius, -Math.PI / 2, -Math.PI / 2 + (Math.PI * 2 * safePct));
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.lineCap = 'round';
            // Optimized: Removed shadowBlur
            ctx.stroke();
        }

        ctx.restore();
    }

    private drawFloatingText(ctx: CanvasRenderingContext2D) {
        this.damageNumbers.forEach(d => {
            if (!d.active) return;

            const lifePct = d.life / d.maxLife;
            const alpha = lifePct < 0.3 ? lifePct / 0.3 : 1.0;

            ctx.globalAlpha = alpha;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.shadowBlur = 0; 

            if (d.type === 'KILL_STREAK') {
                ctx.save();
                ctx.translate(d.x, d.y);
                const pop = Math.min(1, (1 - lifePct) * 5); 
                const pulse = 1 + Math.sin(lifePct * 10) * 0.1;
                const scale = pop * pulse * 1.5; 
                ctx.scale(scale, scale);
                ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;

                const grad = ctx.createLinearGradient(0, -d.size/2, 0, d.size/2);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.5, d.color);
                grad.addColorStop(1, '#000000');

                ctx.lineWidth = 4;
                ctx.lineJoin = 'round';
                ctx.strokeStyle = '#000';
                ctx.strokeText(d.text, 0, 0);
                ctx.fillStyle = grad;
                ctx.fillText(d.text, 0, 0);
                ctx.restore();

            } else if (d.type === 'SHOUT') {
                if (d.isUlt) {
                    const scale = 1 + (1 - lifePct) * 0.1; 
                    ctx.save();
                    ctx.translate(d.x, d.y);
                    ctx.scale(scale, scale);
                    ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;
                    const textMetrics = ctx.measureText(d.text);
                    const w = textMetrics.width / 2 + 25;
                    const h = d.size + 12;

                    const bgGrad = ctx.createLinearGradient(-w - 20, 0, w + 20, 0);
                    bgGrad.addColorStop(0, 'rgba(0,0,0,0)');
                    bgGrad.addColorStop(0.3, 'rgba(2, 6, 23, 0.85)'); 
                    bgGrad.addColorStop(0.7, 'rgba(2, 6, 23, 0.85)');
                    bgGrad.addColorStop(1, 'rgba(0,0,0,0)');

                    ctx.fillStyle = bgGrad;
                    ctx.fillRect(-w - 20, -h/2, w*2 + 40, h);

                    ctx.strokeStyle = d.color;
                    ctx.lineWidth = 2;
                    ctx.globalAlpha = alpha * 0.8;

                    ctx.beginPath(); ctx.moveTo(-w, -h/2); ctx.lineTo(w, -h/2); ctx.stroke();
                    ctx.beginPath(); ctx.moveTo(-w * 0.8, h/2); ctx.lineTo(w * 0.8, h/2); ctx.stroke();

                    ctx.globalAlpha = alpha;
                    // Optimized: Reduced shadowBlur or remove if needed
                    ctx.shadowColor = d.color; ctx.shadowBlur = 0; 
                    ctx.fillStyle = '#fff';
                    ctx.fillText(d.text, 0, 0);
                    ctx.restore();
                } else {
                    ctx.font = `bold ${d.size}px "Segoe UI", sans-serif`;
                    const textMetrics = ctx.measureText(d.text);
                    const padX = 12;
                    const padY = 6;
                    const w = textMetrics.width;
                    const h = d.size;

                    ctx.fillStyle = 'rgba(15, 23, 42, 0.75)'; 
                    ctx.beginPath();
                    if (ctx.roundRect) ctx.roundRect(d.x - w/2 - padX, d.y - h/2 - padY, w + padX*2, h + padY*2, 8);
                    else ctx.rect(d.x - w/2 - padX, d.y - h/2 - padY, w + padX*2, h + padY*2);
                    ctx.fill();

                    ctx.strokeStyle = `rgba(255,255,255,0.15)`;
                    ctx.lineWidth = 1;
                    ctx.stroke();

                    // Optimized: Removed shadowBlur
                    ctx.fillStyle = '#fff'; 
                    ctx.fillText(d.text, d.x, d.y);
                }

            } else {
                // DAMAGE / HEAL / CC
                ctx.font = `900 ${d.size}px "Segoe UI", sans-serif`;

                // Outline to make it readable on any background
                ctx.lineWidth = 3;
                ctx.strokeStyle = 'rgba(0,0,0,0.8)';
                ctx.strokeText(d.text, d.x, d.y);

                ctx.fillStyle = d.color; 
                ctx.fillText(d.text, d.x, d.y);
            }

            ctx.globalAlpha = 1.0;
        });
    }
}

import { Agent } from "../../game";
import { AssetManager } from "../../assets";
import { Team } from "../../../types";
import { SurfaceAssets } from "../../graphics/SurfaceAssets";
import { HEX_SIZE } from "../../../constants";

// Helper to calculate animation progress (0.0 to 1.0)
// Moved here from utils.ts to reduce file count
export function getCastProgress(agent: Agent): number {
    if (agent.castingSkillIdx === -1) return 0;
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return 0;
    const raw = agent.castTimer / skill.cast;
    return Math.max(0, Math.min(1, 1 - raw)); 
}

// Helper: Local Hexagon Trace
function traceHex(ctx: CanvasRenderingContext2D, r: number) {
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
        const angle = i * Math.PI / 3;
        const x = r * Math.cos(angle);
        const y = r * Math.sin(angle);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
    }
    ctx.closePath();
}

export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const isBlue = agent.team === Team.BLUE;
    const color = isBlue ? '#60a5fa' : '#f87171';

    const feetX = Math.round(physX);
    const feetY = Math.round(physY - physZ); 

    ctx.save();
    ctx.translate(feetX, feetY); // Center at shadow point
    ctx.save();
    ctx.scale(1, 0.58); 
    ctx.lineDashOffset = -t * 20;
    ctx.globalAlpha = 0.6;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.setLineDash([8, 4]);
    traceHex(ctx, 18);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.restore();

    if (physZ > 5) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.3;
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(0, physZ); ctx.stroke(); // Vertical line from shadow to body
    }
    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const color = agent.team === Team.BLUE ? '#bae6fd' : '#fecaca'; 
    ctx.save();
    ctx.translate(0, 5); 
    ctx.scale(1, 0.5); 
    ctx.rotate(t * 8); 
    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.globalAlpha = 0.5 + Math.sin(t * 20) * 0.2; 
    // Hexagonal Thruster Ring
    traceHex(ctx, 15);
    ctx.stroke();
    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    // --- 1. HEXAGONAL ORBITAL BITS ---
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const orbitRadius = 25;
    for (let i = 0; i < 3; i++) {
        const offset = i * (Math.PI * 2 / 3);
        const ox = Math.round(Math.cos(t * 6 + offset) * orbitRadius);
        const oy = Math.round(Math.sin(t * 6 + offset) * orbitRadius * 0.5) - 35;

        ctx.save();
        ctx.translate(ox, oy);
        ctx.rotate(t * 10);
        ctx.beginPath();
        traceHex(ctx, 4 * progress); // Small Hex Bit
        ctx.fillStyle = '#fff';
        // PERF: Removed shadowBlur
        ctx.fill();
        ctx.restore();
    }
    ctx.restore();

    if (skill.type === 'AOE') {
        drawDomainExpansion(ctx, agent, t, color, progress);
    }
}

export function drawDomainExpansion(ctx: CanvasRenderingContext2D, agent: Agent, t: number, color: string, progress: number) {
    ctx.save();
    ctx.translate(0, -40); 
    const scale = 0.5 + progress * 0.5;
    ctx.scale(scale, scale * 0.5); 
    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.globalCompositeOperation = 'screen';
    ctx.rotate(t * 2);
    traceHex(ctx, 60);
    ctx.stroke();
    ctx.restore();
}

export function drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;
    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    ctx.translate(0, -40); 
    const size = Math.round(50 * (0.2 + progress * 0.8));
    ctx.globalCompositeOperation = 'screen';

    // Hexagonal Gradient Fill
    // We can't do radial gradient easily on a path, so we just use stacked hexes
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.3;
    traceHex(ctx, size); ctx.fill();

    ctx.fillStyle = '#fff';
    ctx.globalAlpha = 0.5;
    traceHex(ctx, size * 0.6); ctx.fill();

    ctx.restore();
}

export function drawSkillGroundIndicator(
    ctx: CanvasRenderingContext2D, 
    x: number, y: number, 
    color: string, 
    t: number, 
    progress: number, 
    skillRadius: number, 
    type: string, 
    isAOE: boolean
) {
    ctx.save();
    ctx.translate(Math.round(x), Math.round(y));

    // Calculate size
    const maxPx = Math.max(1, skillRadius) * HEX_SIZE;
    const currentRadius = maxPx * progress;

    ctx.scale(1, 0.58); // Isometric flatten

    // --- LAYER 1: BASE FIELD (Hex Fill) ---
    traceHex(ctx, currentRadius);
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.35; 
    ctx.fill();

    // --- LAYER 2: ENERGY RIM (Hex Glow) ---
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = color;
    ctx.lineWidth = 5;
    ctx.globalAlpha = 0.9;
    // PERF: Removed expensive shadowBlur, simulated with layers or alpha
    traceHex(ctx, currentRadius);
    ctx.stroke();

    // Fake Glow Layer (Cheaper)
    ctx.lineWidth = 2;
    ctx.strokeStyle = '#fff';
    ctx.globalAlpha = 0.4;
    traceHex(ctx, currentRadius + 2);
    ctx.stroke();

    ctx.restore();

    // --- LAYER 3: RUNIC BORDER (Rotating Hex) ---
    ctx.save();
    ctx.rotate(t * 1.5); 
    ctx.strokeStyle = '#fff'; 
    ctx.lineWidth = 2;
    ctx.setLineDash([10, 8]); // Dashed pattern
    ctx.globalAlpha = 0.8;
    traceHex(ctx, currentRadius + 2);
    ctx.stroke();
    ctx.restore();

    ctx.restore();
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill) {
            ctx.save();
            ctx.translate(0, Math.round(-110));

            // Hex Glow Background
            ctx.globalAlpha = 0.3 * (0.5 + Math.sin(t * 10) * 0.1);
            ctx.fillStyle = skill.color;
            traceHex(ctx, 40);
            ctx.fill();

            ctx.restore();
        }
    }
}

export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;
    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    if (agent.stunTimer > 0) {
        ctx.translate(0, Math.round(-65));
        const angle = t * 5;
        const x = Math.round(Math.cos(angle) * 20);
        const y = Math.round(Math.sin(angle) * 6); 
        ctx.fillStyle = '#facc15';

        // Spinning Star/Hex
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(t * 10);
        traceHex(ctx, 4);
        ctx.fill();
        ctx.restore();
    }
    ctx.restore();
}

import { Agent } from "../game";
import { Particle } from "../systems/vfx/state";
